HW.add({ders:"hayat", sinif:2, uniteler:[
  {ad:"Ben ve Okulum", konular:[
    {id:"hb2-okul-iletisim", ad:"Okulum, Kurallar ve İletişim", e:"🏫",
     anlat:[
       {b:"Okulumuzun çalışanları", m:"Okulda öğretmenler, müdür ve müdür yardımcıları, rehber öğretmen, kütüphaneci, hizmetliler ve güvenlik görevlileri çalışır. Her görevli okulun düzeni için önemlidir.", o:"Sorunumuzu rehber öğretmene anlatabiliriz."},
       {b:"Kurallar neden gerekli?", m:"Kurallar, birlikte yaşarken herkesin haklarını korur. Sınıf ve okul kurallarını birlikte belirleriz. Kurallara uyan kişi başkalarına saygı göstermiş olur.", o:"Kütüphanede sessiz oluruz, çünkü herkes okumak ister."},
       {b:"Nazik iletişim", m:"Konuşurken karşımızdakini dinleriz. 'Lütfen', 'teşekkür ederim', 'özür dilerim' sözleri iletişimi güzelleştirir. Anlaşmazlıkları bağırarak değil, konuşarak çözeriz.", o:"Sözünü kesmeden dinlerim, sonra konuşurum."},
       {b:"Sınıfta işbirliği", m:"Grup çalışmasında görev paylaşırız. Herkesin fikri değerlidir. İşi birlikte yapınca daha çabuk ve güzel biter.", o:"Biri yazar, biri boyar, biri anlatır."}
     ],
     ipucu:"Dinle, bekle, nazik ol, paylaş: Sınıfın dört anahtarı!",
     kartlar:[["Sorun anlatılacak okul çalışanı","Rehber öğretmen"],["Okulu temizleyen görevli","Hizmetli"],["Kitap ödünç aldığımız yer","Kütüphane"],["Grup çalışmasında ne yaparız?","Görev paylaşırız"],["Anlaşmazlığı nasıl çözeriz?","Konuşarak"],["Karşımızdakine ne yaparız?","Onu dinleriz"]],
     sorular:[
       {s:"Okulda yaşadığı bir sorunu anlatmak isteyen öğrenci kime gidebilir?", c:["Rehber öğretmene","Bahçıvana","Satıcıya","Komşuya"], a:"Rehber öğretmen öğrencilerin sorunlarında yardımcı olur."},
       {s:"Okul kuralları neden vardır?", c:["Herkesin haklarını korumak için","Çocukları sıkmak için","Oyunları engellemek için","Öğretmen istediği için"], a:"Kurallar birlikte yaşamayı kolaylaştırır ve herkesi korur."},
       {s:"Kütüphanede neden sessiz olmalıyız?", c:["Diğer kişiler okuyabilsin diye","Sessiz olmak zorunda olduğumuz için","Kitaplar uyanmasın diye","Işık yanmasın diye"], a:"Sessizlik, herkesin dikkatini toplayıp okumasını sağlar."},
       {s:"Arkadaşınla anlaşmazlık yaşadın. En doğru davranış hangisidir?", c:["Sakince konuşup çözmek","Bağırmak","Vurmak","Küsüp konuşmamak"], a:"Anlaşmazlıklar konuşarak çözülür."},
       {s:"Arkadaşın konuşurken ne yapmalısın?", c:["Onu dinlemeliyim","Sözünü kesmeliyim","Başka şey yapmalıyım","Dalga geçmeliyim"], a:"Dinlemek saygı ve iyi iletişimdir."},
       {s:"Hangisi nazik bir söz değildir?", c:["Çekil önümden!","Lütfen yer açar mısın?","Teşekkür ederim","Özür dilerim"], a:"Emir verir gibi konuşmak nazik değildir."},
       {s:"Grup çalışmasında en doğru davranış hangisidir?", c:["Görevleri paylaşmak","Her işi tek başına yapmak","Hiçbir şey yapmamak","Kimseyi dinlememek"], a:"Görev paylaşımı işbirliğidir."},
       {s:"Sınıf kuralları nasıl belirlenirse herkes daha kolay uyar?", c:["Hep birlikte karar verilirse","Sadece güçlü öğrenciler belirlerse","Hiç konuşulmazsa","Kimse bilmezse"], a:"Birlikte belirlenen kurallar daha çok benimsenir."},
       {s:"Tahtaya çıkan arkadaşın hata yaptı. Sınıf nasıl davranmalı?", c:["Ona nazikçe yardım etmeli","Hep birlikte gülmeli","Onu azarlamalı","Yerine oturtmalı"], a:"Hata yapan arkadaşımıza saygıyla destek oluruz."},
       {s:"Okulda biri sana kötü davranıyor. Ne yapmalısın?", c:["Bir yetişkine söylemeliyim","Hiç kimseye söylememeliyim","Ben de aynısını yapmalıyım","Okula gitmemeliyim"], a:"Kötü davranışı bir yetişkine anlatmak doğru ve güvenli yoldur."}
     ]
    },
    {id:"hb2-ozellikler-duygular", ad:"Özelliklerim ve Duygularım", e:"🪞",
     anlat:[
       {b:"Benim özelliklerim", m:"Boyum, kilom, saç ve göz rengim fiziksel özelliklerimdir. Sevdiğim şeyler, yeteneklerim ve davranışlarım kişisel özelliklerimdir. Herkes biriciktir.", o:"Ben resim yapmayı severim, arkadaşım futbol oynamayı."},
       {b:"Duyguları tanıma", m:"Sevinç, üzüntü, korku, kızgınlık, utanma ve heyecan gibi duygularımız vardır. Duygular vücudumuzda belirti verir: kalp hızlanır, yüzümüz kızarır.", o:"Heyecanlanınca kalbim hızlı atar."},
       {b:"Duyguları yönetme", m:"Kızgınken derin nefes alırım ve on'a kadar sayarım. Duygumu 'Ben ... hissediyorum' diyerek anlatırım. Kendimi ve başkasını incitmem.", o:"'Çok kızdım' demek, vurmaktan iyidir."},
       {b:"Farklılıklara saygı", m:"İnsanlar farklı görünür, farklı sevdiklerine sahiptir. Farklılıklar bizi zengin yapar. Kimseyle görünüşü yüzünden alay etmeyiz.", o:"Arkadaşım gözlük takıyor; bu onu özel kılar."}
     ],
     ipucu:"Dur, nefes al, say, anlat: Kızgınlık kolayca geçer!",
     kartlar:[["Boy ve saç rengi nasıl bir özellik?","Fiziksel"],["Sevdiklerimiz nasıl özellik?","Kişisel"],["Heyecanlanınca ne hızlanır?","Kalp atışı"],["Kızınca ne yapmalıyız?","Derin nefes almalıyız"],["Herkes nasıldır?","Biriciktir"],["Farklılıklara karşı ne yaparız?","Saygı gösteririz"]],
     sorular:[
       {s:"Hangisi fiziksel bir özelliktir?", c:["Göz rengi","Hobi","Sevdiği yemek","Yeteneği"], a:"Göz rengi bedenimizle ilgili, fiziksel bir özelliktir."},
       {s:"Hangisi kişisel bir özelliktir?", c:["Çalışkan olmak","Boy uzunluğu","Saç rengi","Ayak numarası"], a:"Çalışkan olmak davranışla ilgili bir kişisel özelliktir."},
       {s:"Heyecanlandığımızda vücudumuzda ne olabilir?", c:["Kalp hızlı atar","Saçlarımız uzar","Boyumuz uzar","Gözümüzün rengi değişir"], a:"Heyecanla kalp atışı hızlanabilir."},
       {s:"Çok kızdığında ilk ne yapmalısın?", c:["Derin nefes alıp sakinleşmeliyim","Eşyaları fırlatmalıyım","Bağırmalıyım","Kapıyı çarpmalıyım"], a:"Sakinleşmek, duyguyu yönetmenin ilk adımıdır."},
       {s:"'Utandım' ifadesi hangi gruptadır?", c:["Duygu","Hayvan","Yiyecek","Eşya"], a:"Utanma bir duygudur."},
       {s:"Arkadaşın gözlük takıyor diye ona ne yapmalısın?", c:["Saygı göstermeliyim","Onunla alay etmeliyim","Ondan uzak durmalıyım","Gözlüğünü almalıyım"], a:"Farklılıklara saygı göstermek gerekir."},
       {s:"Sınavdan önce kalbi hızlı atan Elif nasıl hissediyordur?", c:["Heyecanlı","Uykulu","Aç","Üşümüş"], a:"Kalp çarpıntısı genellikle heyecan işaretidir."},
       {s:"Hangisi duygumuzu doğru anlatmaktır?", c:["'Sana kırıldım.'","Susup bağırmak","Vurmak","Eşyaları dağıtmak"], a:"Duyguyu sözle anlatmak sağlıklıdır."},
       {s:"Herkesin biricik olması ne demektir?", c:["Hiç kimse tıpatıp aynı değildir","Herkes aynı şeyi sever","Herkes aynı görünür","Kimsenin özelliği yoktur"], a:"Her insanın kendine özgü özellikleri vardır."},
       {s:"Üzgün bir arkadaşını görünce nasıl davranmak en uygunudur?", c:["Yanına gidip ona nazikçe neden üzgün olduğunu sormak","Onu görmezden gelmek","Ona gülmek","Hemen uzaklaşmak"], a:"İlgi ve destek, üzgün arkadaşımızı rahatlatır."}
     ]
    },
    {id:"hb2-arkadaslik-empati", ad:"Arkadaşlık ve Empati", e:"🤗",
     anlat:[
       {b:"İyi arkadaş", m:"İyi arkadaş dürüsttür, sözünü tutar, paylaşır ve yardım eder. Arkadaşının sırrını gereksiz yere anlatmaz.", o:"Sözümü tutarım."},
       {b:"Empati", m:"Empati, karşımdakinin yerine kendimizi koyup duygusunu anlamaktır. Arkadaşım üzülüyorsa ne hissettiğini düşünürüm.", o:"Düşen arkadaşıma 'İyi misin?' derim."},
       {b:"Anlaşmazlık", m:"Arkadaşımla anlaşamazsam önce sakinleşirim. Sonra düşüncemi nazikçe söylerim. Onu da dinlerim. Birlikte çözüm ararım.", o:"Sırayla konuşuruz."},
       {b:"Zorbalık yapmayalım", m:"Bir arkadaşıma vurmak, alay etmek ya da onu dışlamak zorbalıktır. Zorbalık görürsem bir büyüğe söylerim.", o:"Alay edene 'Bu doğru değil.' derim."}
     ],
     ipucu:"Empati: Onun yerine geç, duygusunu anla; zorbalığa hayır, yardıma evet!",
     kartlar:[["Başkasının yerine kendini koymak","Empati"],["Alay etmek, dışlamak, vurmak","Zorbalık"],["İyi arkadaş sözünü ne yapar?","Tutar"],["Anlaşmazlıkta ilk ne yaparız?","Sakinleşiriz"],["Zorbalık görünce ne yaparız?","Büyüğe söyleriz"],["Arkadaşını dinlemek neyi gösterir?","Saygıyı"]],
     sorular:[
       {s:"Başkasının yerine kendini koyarak duygusunu anlamaya ne denir?", c:["Empati","Zorbalık","Kıskançlık","İnat"], a:"Empati, karşımızdakini anlamaya çalışmaktır."},
       {s:"Arkadaşın düşüp ağlıyor. Ne yaparsın?", c:["Yanına gidip iyi olup olmadığını sorarım","Gülerim","Görmezden gelirim","Onu bırakıp giderim"], a:"Empati kuran yardıma koşar."},
       {s:"Hangisi zorbalıktır?", c:["Arkadaşıyla alay etmek","Arkadaşıyla paylaşmak","Arkadaşına yardım etmek","Arkadaşını dinlemek"], a:"Alay etmek ve dışlamak zorbalıktır."},
       {s:"Zorbalık görürsen ne yaparsın?", c:["Bir büyüğe söylerim","Bakar geçerim","Ben de katılırım","Saklanırım"], a:"Zorbalığı yetişkinlere bildirmeliyiz."},
       {s:"Arkadaşınla anlaşamadın. İlk ne yapmalısın?", c:["Sakinleşmeliyim","Bağırmalıyım","Vurmalıyım","Küsmeliyim"], a:"Sakinleşmek sorunu çözmeye yardım eder."},
       {s:"İyi bir arkadaşın özelliği hangisidir?", c:["Sözünü tutmak","Yalan söylemek","Eşyaları saklamak","Alay etmek"], a:"Sözünü tutan güvenilir olur."},
       {s:"Yeni gelen arkadaş tek başına duruyor. Ne yaparsın?", c:["Onu oyuna çağırırım","Hiç konuşmam","Ona gülerim","Onu uzaklaştırırım"], a:"Dışlamak yerine içine alırız."},
       {s:"Arkadaşın sana sır verdi. Ne yaparsın?", c:["Başkasına anlatmam","Hemen herkese söylerim","Gülerek anlatırım","Yazıp asarım"], a:"Sır tutmak güven oluşturur."},
       {s:"Fikrin arkadaşınınkinden farklı. Ne yaparsın?", c:["Nazikçe konuşup dinlerim","Bağırırım","Küserim","Arkadaşlığı bitiririm"], a:"Farklı düşünceye saygı gösteririz."},
       {s:"Hangi cümle empati içerir?", c:["'Üzüldüğünü anlıyorum, yardım edeyim mi?'","'Bana ne!'","'Ağlama, çok ayıp!'","'Boşuna üzülüyorsun.'"], a:"Empati, duyguyu anlayıp yardım etmeyi içerir."}
     ]}
  ]},
  {ad:"Ailem ve Toplum", konular:[
    {id:"hb2-aile-akraba", ad:"Ailem ve Akrabalarım", e:"👪",
     anlat:[
       {b:"Aile ve akraba", m:"Aile, anne, baba ve çocuklardan oluşur. Akrabalar ise aile büyüklerimizin yakınlarıdır. Dede, nine, amca, hala, dayı ve teyze akrabalarımızdır.", o:"Babamın kız kardeşi benim halamdır."},
       {b:"Akrabalık adları", m:"Babamın erkek kardeşi amca, kız kardeşi hala olur. Annemin erkek kardeşi dayı, kız kardeşi teyze olur. Onların çocukları kuzenimizdir.", o:"Teyzemin oğlu benim kuzenimdir."},
       {b:"Aile içinde roller", m:"Ailede herkesin sorumluluğu vardır. Büyükler çocuklara bakar, çocuklar da yardımlaşır. Herkesin sözü dinlenir ve saygı gösterilir.", o:"Bulaşıkları kardeşimle birlikte kaldırırız."},
       {b:"Akrabalar ve ziyaret", m:"Bayramlarda ve özel günlerde akrabalarımızı ziyaret ederiz. Büyüklerin elini öper, küçüklerimizi severiz. Birbirimize destek oluruz.", o:"Bayramda dedemin elini öperim."}
     ],
     ipucu:"Baba tarafı: amca-hala. Anne tarafı: dayı-teyze!",
     kartlar:[["Babanın erkek kardeşi","Amca"],["Babanın kız kardeşi","Hala"],["Annenin erkek kardeşi","Dayı"],["Annenin kız kardeşi","Teyze"],["Amca veya teyzenin çocuğu","Kuzen"],["Anne ve babanın annesi-babası","Dede ve nine"]],
     sorular:[
       {s:"Babamın kız kardeşine ne denir?", c:["Hala","Teyze","Yenge","Abla"], a:"Babanın kız kardeşi halamızdır."},
       {s:"Annemin erkek kardeşine ne denir?", c:["Dayı","Amca","Enişte","Dede"], a:"Annenin erkek kardeşi dayıdır."},
       {s:"Babamın erkek kardeşine ne denir?", c:["Amca","Dayı","Hala","Teyze"], a:"Babanın erkek kardeşi amcadır."},
       {s:"Annemin kız kardeşi benim neyimdir?", c:["Teyzem","Halam","Yengem","Ablam"], a:"Annenin kız kardeşi teyzedir."},
       {s:"Amcamın kızı benim neyimdir?", c:["Kuzenim","Kardeşim","Halam","Dayım"], a:"Amca, dayı, hala ya da teyzenin çocukları kuzenimizdir."},
       {s:"Hangisi akrabalarımızı ziyaret etmek için uygun bir zamandır?", c:["Bayram günleri","Sınav sırasında okulda","Gece yarısı","Hiçbir zaman"], a:"Bayramlarda ve özel günlerde akraba ziyareti geleneğimizdir."},
       {s:"Hangisi aile içinde yardımlaşmaya örnektir?", c:["Kardeşimle sofrayı kurmak","Odamı dağıtmak","Evde bağırmak","Annemi dinlememek"], a:"Ailede herkes iş bölümü yapar ve yardımlaşır."},
       {s:"Dedemizin ya da ninemizin evine gidince nasıl davranırız?", c:["Saygılı ve nazik","Bağıran","Hiç konuşmayan","Eşyaları karıştıran"], a:"Büyüklere saygı göstermek önemlidir."},
       {s:"Ali'nin annesinin kardeşi Ayşe'dir. Ayşe, Ali'nin neyidir?", c:["Teyzesi","Halası","Yengesi","Ablası"], a:"Annenin kız kardeşi teyzedir."},
       {s:"Bir ailede sorumluluklar nasıl olmalıdır?", c:["Herkes elinden geleni yapmalı","Yalnızca anne yapmalı","Hiç kimse yapmamalı","Yalnızca çocuklar yapmalı"], a:"Ailede iş birliği herkesin sorumluluğudur."}
     ]
    },
    {id:"hb2-evde-tasarruf", ad:"Evde Sorumluluklar ve Tasarruf", e:"💡",
     anlat:[
       {b:"Evdeki sorumluluklar", m:"Evde yaşın ve gücüne göre görevler alırım. Yatağımı toplamak, çantamı hazırlamak ve oyuncaklarımı yerine koymak benim görevimdir. Sorumluluğumu yerine getirmek güvenilir yapar.", o:"Yarınki ders kitaplarımı akşamdan hazırlarım."},
       {b:"Kaynak tasarrufu", m:"Su, elektrik ve doğal gaz sınırlı kaynaklardır. Tasarruf yapmak bunları uzun süre kullanmamızı sağlar. Duşta süreyi kısa tutarız, kullanmadığımız cihazı kapatırız.", o:"Telefon şarjı dolunca fişi çekerim."},
       {b:"Yiyecek israfı", m:"Ekmek ve yiyecekleri israf etmeyiz. Tabağımıza yiyebileceğimiz kadar alırız. Artan yemekleri buzdolabında saklarız.", o:"Yemek artıklarını çöpe atmadan önce düşünürüm."},
       {b:"Para ve harçlık", m:"Aldığım harçlığı dikkatli harcarım ve bir kısmını biriktiririm. Para kazanmak emek ister. Önce ihtiyaçlarımı düşünürüm.", o:"Bisiklet için her hafta biraz biriktiririm."}
     ],
     ipucu:"Kapat, söndür, biriktir, israf etme: Tasarruf dört adımda!",
     kartlar:[["Sınırlı kaynaklara örnek","Su ve elektrik"],["Kullanmadığımız cihazı ne yaparız?","Kapatırız"],["İsrafı önlemek için ne yaparız?","Gerektiği kadar alırız"],["Harçlığın bir kısmını ne yaparız?","Biriktiririz"],["Sorumluluk almak bizi nasıl yapar?","Güvenilir"],["Artan yemeği nerede saklarız?","Buzdolabında"]],
     sorular:[
       {s:"Hangisi sınırlı bir kaynaktır?", c:["Su","Hayal","Gülümseme","Sevgi"], a:"Su sınırlı bir kaynaktır; tasarruflu kullanılmalıdır."},
       {s:"Duşta tasarruf için ne yapmalıyız?", c:["Süreyi kısa tutmalıyız","Suyu açık bırakıp çıkmalıyız","Sıcak suyla uzun kalmalıyız","Musluğu bozmalıyız"], a:"Kısa duş su ve enerji tasarrufu sağlar."},
       {s:"Şarj aletini işi bitince prizde bırakmak neden iyi değildir?", c:["Elektrik boşa gider","Şarj aleti kızar","Kablo yıkanır","Prizden ses çıkar"], a:"Gereksiz bağlantılar elektrik tüketimine ve riske yol açabilir."},
       {s:"Tabağımıza nasıl yemek almalıyız?", c:["Yiyebileceğimiz kadar","Hep dolu","Hiç almamalıyız","Fazla alıp bırakmalıyız"], a:"Yiyebileceğimiz kadar alarak israfı önleriz."},
       {s:"Harçlığımızı nasıl kullanmalıyız?", c:["Düşünerek ve biriktirerek","Hemen tamamını harcayarak","Kaybederek","Atarak"], a:"Planlı harcama ve biriktirme tasarruftur."},
       {s:"Akşamdan okul çantasını hazırlayan öğrenci ne yapmış olur?", c:["Sorumluluğunu yerine getirmiştir","Vakit kaybetmiştir","Sabah işini kolaylaştırmaz","Kural çiğnemiştir"], a:"Önceden hazırlanmak sorumluluk bilincidir."},
       {s:"Hangisi enerji tasarrufu sağlar?", c:["Güneşli odada ışığı kapatmak","Her odada ışığı yakmak","Televizyonu boşuna açık tutmak","Buzdolabı kapağını açık bırakmak"], a:"Gün ışığı yeterliyse lambayı kapatırız."},
       {s:"Neden tasarruf yapmalıyız?", c:["Kaynaklar sınırlı olduğu için","Cimri olmak için","Moda olduğu için","Zorunlu olduğu için"], a:"Kaynakları gelecekte de kullanabilmek için tasarruf ederiz."},
       {s:"Bayat ekmekle ne yapmak israfı önler?", c:["Ekmek kurusu ya da galeta unu yapmak","Çöpe atmak","Sokağa fırlatmak","Yere dökmek"], a:"Bayat ekmek başka yiyeceklerde değerlendirilebilir."},
       {s:"Mina harçlığıyla hemen oyuncak aldı, sonra bisiklet için para bulamadı. Ona hangi öneri uygundur?", c:["Önce hedef belirleyip biriktirmeli","Hiç harcamamalı","Daha fazla oyuncak almalı","Parayı saklamamalı"], a:"Hedef koyup biriktirmek planlı harcamadır."}
     ]
    }
  ]},
  {ad:"Sağlığım ve Güvenliğim", konular:[
    {id:"hb2-beslenme-hijyen", ad:"Beslenme ve Kişisel Bakım", e:"🥗",
     anlat:[
       {b:"Dengeli beslenme", m:"Sağlıklı büyümek için her gün süt ürünleri, et-yumurta-baklagil, sebze-meyve ve tahıl yeriz. Hiçbir besin tek başına yeterli değildir.", o:"Bir tabakta sebze, et ve pilav birlikte olabilir."},
       {b:"Öğünler ve su", m:"Gün içinde kahvaltı, öğle ve akşam yemeği yeriz. Ara öğünlerde meyve ya da kuruyemiş seçeriz. Gün boyunca yeterince su içeriz.", o:"Okulda su matarası taşırım."},
       {b:"Kişisel temizlik", m:"Düzenli duş alır, tırnaklarımızı keseriz. Dişlerimizi sabah ve akşam fırçalarız. Giysilerimizi temiz tutarız. Temizlik hastalıklardan korur.", o:"Tırnak diplerinde mikrop birikir."},
       {b:"Uyku ve hareket", m:"Sağlıklı olmak için yeterli uyumalı ve hareket etmeliyiz. Çocuklar için gece yaklaşık 9-11 saat uyku gerekir. Açık havada oynamak da çok iyidir.", o:"Her gün parkta yürüyüş yaparım."}
     ],
     ipucu:"Dengeli ye, bol su iç, temiz ol, iyi uyu: Sağlık senin!",
     kartlar:[["Büyümek için ne yeriz?","Dengeli besin"],["Ara öğüne iyi örnek","Meyve"],["Hangi içecek günlük önemli?","Su"],["Tırnaklarımızı ne yaparız?","Düzenli keseriz"],["Diş fırçalama sayısı","Günde iki kez"],["Hareket etmek bize ne sağlar?","Sağlıklı olmak"]],
     sorular:[
       {s:"Dengeli beslenme ne demektir?", c:["Her gruptan besin yemek","Sadece tatlı yemek","Hiç sebze yememek","Sadece et yemek"], a:"Farklı besin gruplarından yeterli ve çeşitli yemek dengeli beslenmedir."},
       {s:"Hangisi ara öğün için en uygundur?", c:["Bir avuç fındık ve meyve","Büyük boy cips","Gazlı içecek","Çok şekerli çikolata"], a:"Meyve ve kuruyemiş sağlıklı ara öğündür."},
       {s:"Günlük suyumuzu nasıl almalıyız?", c:["Gün içine yayarak","Hiç içmeyerek","Sadece gazlı içerek","Sadece geceleri"], a:"Gün içinde düzenli su içmek gerekir."},
       {s:"Tırnaklarımızı neden kısa tutarız?", c:["Altında mikrop birikmesin diye","Daha güzel görünsün diye","Hemen uzamasın diye","Kalem tutmayalım diye"], a:"Tırnak altında kir ve mikrop birikebilir."},
       {s:"Süt ve yoğurt hangi besin grubundandır?", c:["Süt ürünleri","Sebzeler","Tahıllar","Meyveler"], a:"Süt, yoğurt ve peynir süt ürünleridir."},
       {s:"Yeterli uyumazsak ne olabilir?", c:["Derste dikkatimiz dağılır","Hemen boyumuz uzar","Hiç hasta olmayız","Çok enerjik oluruz"], a:"Uyku eksikliği yorgunluğa ve dikkatsizliğe yol açar."},
       {s:"Hangisi hareketli bir sağlık alışkanlığıdır?", c:["Her gün parkta yürümek","Sürekli ekranda oyun oynamak","Gün boyu yatmak","Sandalyede oturmak"], a:"Düzenli hareket vücudu güçlendirir."},
       {s:"Okulda yemekten önce elimizi neden yıkarız?", c:["Mikroplar ağzımıza geçmesin diye","Eller soğusun diye","Süs olsun diye","Sabun bitsin diye"], a:"Eller mikrop taşıyabilir; yıkamak bizi hastalıklardan korur."},
       {s:"Kahvaltı yapmayan öğrenci için hangisi doğru olabilir?", c:["Dersin ortasında yorgun ve aç hisseder","Daha güçlü olur","Hiç su içmesi gerekmez","Daha hızlı büyür"], a:"Kahvaltı güne enerjiyle başlamamızı sağlar."},
       {s:"Hangi tabak daha dengelidir?", c:["Sebze, et ve pilav","Sadece kızartma","Sadece tatlı","Sadece ekmek"], a:"Farklı besin gruplarını içeren öğün daha dengelidir."}
     ]
    },
    {id:"hb2-saglik-hastalik", ad:"Hastalıklardan Korunma ve Ekran", e:"🩺",
     anlat:[
       {b:"Hastalıklardan korunma", m:"Ellerimi sık yıkarım. Hapşırırken ağzımı mendille ya da dirseğimle kapatırım. Hasta arkadaşımın eşyasını kullanmam.", o:"Dirseğime hapşırırım."},
       {b:"Hasta olunca", m:"Hasta olursam öğretmenime ya da ailemize haber veririm. Doktora gider, ilaçları doktorun söylediği gibi kullanırım.", o:"İlacı büyükle içerim."},
       {b:"Aşılar", m:"Aşılar bizi bazı hastalıklardan korur. Doktorun söylediği zamanlarda aşı yaptırırız.", o:"Aşı olunca korunurum."},
       {b:"Ekran kullanımı", m:"Telefon, tablet ve televizyona uzun süre bakmak gözlere ve uykuya zarar verir. Ekran sürem sınırlı olmalı. Çok oturmayıp hareket ederim.", o:"Ekranı kapatıp oynarım."}
     ],
     ipucu:"El yıka, dirseğe hapşır, aşıyı unutma, ekrana az bak!",
     kartlar:[["Mikroptan korunmak için ne yıkarız?","Ellerimizi"],["Hapşırırken neyi kapatırız?","Ağzımızı ve burnumuzu"],["Bizi hastalıktan koruyan uygulama","Aşı"],["Çok ekran neyi bozar?","Gözleri ve uykuyu"],["Hasta olunca kime gideriz?","Doktora"],["Ekrandan sonra ne yaparız?","Hareket ederiz"]],
     sorular:[
       {s:"Hastalıklardan korunmak için ne yapmalıyız?", c:["Ellerimizi sık yıkamalıyız","Hiç yıkamamalıyız","Pis eşya kullanmalıyız","Yerdeki yemeği yemeliyiz"], a:"El temizliği mikropları azaltır."},
       {s:"Hapşırırken ne yaparız?", c:["Ağzımızı mendille ya da dirseğimizle kapatırız","Elimizle ağzımızı açık bırakırız","Başkasına doğru hapşırırız","Önlem almadan hapşırırız"], a:"Mikropların yayılmasını önleriz."},
       {s:"Aşı ne işe yarar?", c:["Bazı hastalıklardan korur","Boyu uzatır","Uyutur","Acıktırır"], a:"Aşılar vücudu hastalıklara karşı hazırlar."},
       {s:"Hasta olduğunda ilaç nasıl kullanılır?", c:["Doktorun söylediği gibi","Canımın istediği kadar","Arkadaşımın verdiği gibi","Tatlı gelirse fazla"], a:"İlaç doktor önerisiyle kullanılır."},
       {s:"Çok ekrana bakmanın zararı nedir?", c:["Gözleri yorar","Güçlendirir","Boyu uzatır","Sesi güzelleştirir"], a:"Uzun ekran süresi göz ve uyku sağlığını bozar."},
       {s:"Hasta arkadaşın öksürüyor. Ne yaparsın?", c:["Biraz uzak durup elimi yıkarım","Aynı bardaktan içerim","Ona sarılıp öperim","Yüzüne bakarak öksürürüm"], a:"Mesafe ve temizlik bulaşı azaltır."},
       {s:"Ekran süresinden sonra ne yapmalıyız?", c:["Dışarıda oynamalıyız","Yine ekrana bakmalıyız","Uyumalıyız","Uzun süre oturmalıyız"], a:"Hareket sağlığı korur."},
       {s:"Mendili kullandıktan sonra ne yaparız?", c:["Çöpe atar, elimizi yıkarız","Cebimize koyarız","Arkadaşa veririz","Yere atarız"], a:"Kullanılmış mendil çöpe atılır."},
       {s:"Hangisi sağlıklı bir alışkanlıktır?", c:["Düzenli uyumak","Geceleri tablette oynamak","Elleri yıkamamak","Çok şeker yemek"], a:"Düzenli uyku sağlık için önemlidir."},
       {s:"Ateşin var ve halsizsin. Ne yaparsın?", c:["Büyüğüme söyleyip doktora giderim","Okula giderim","Kimseye söylemem","Soğuk su içerim"], a:"Ateşte büyüklere haber verip doktora gideriz."}
     ]},
    {id:"hb2-ev-okul-guvenlik", ad:"Evde ve Okulda Güvenlik", e:"🛡️",
     anlat:[
       {b:"Evde tehlikeler", m:"Prizler, sıcak su, ocak, ilaçlar ve temizlik malzemeleri tehlikelidir. Bunlara tek başıma dokunmam.", o:"Ocağa yaklaşmam."},
       {b:"Elektrik", m:"Islak elle prize ya da elektrikli eşyaya dokunmam. Fişi kabloyu çekerek değil, tutarak çekerim. Çıplak kablo görürsem uzak dururum.", o:"Büyüğüme haber veririm."},
       {b:"Okulda güvenlik", m:"Okulda koşarak merdiven inmem. Arkadaşımı itmem. Keskin aletleri dikkatli kullanırım. Sınıf ve bahçe kurallarına uyarım.", o:"Merdivende yürürüm."},
       {b:"Yardım isteme", m:"Bir tehlike olunca büyüklerime ya da öğretmenime hemen söylerim. Acil durumda 112'yi ararım.", o:"Duman görünce hemen söylerim."}
     ],
     ipucu:"Ocak, priz, ilaç: Büyük yanımdayken! Tehlike varsa hemen haber!",
     kartlar:[["Islak elle neye dokunulmaz?","Prize"],["Acil durum numarası","112"],["Merdivende nasıl iner?","Yürüyerek"],["Tehlike olunca kime söyleriz?","Büyüğe/öğretmene"],["İlacı kim verir?","Büyükler"],["Kibrit ve çakmak kimlere verilmez?","Çocuklara"]],
     sorular:[
       {s:"Hangisine büyük yanımda değilken dokunmamalıyım?", c:["Ocağa","Yastığıma","Defterime","Çantama"], a:"Ocak yangın ve yanık tehlikesi taşır."},
       {s:"Islak elle prize dokunmak neden tehlikelidir?", c:["Elektrik çarpabilir","Su biter","Priz parlar","Isınır"], a:"Su elektriği iletir; elektrik çarpması olabilir."},
       {s:"Merdivende nasıl hareket etmelisin?", c:["Yürüyerek ve tutunarak","Koşarak","Atlayarak","İterek"], a:"Merdivende koşmak düşmeye neden olur."},
       {s:"İlacı ne zaman kullanabilirim?", c:["Büyüklerim verirse","İstediğimde","Arkadaşım verirse","Tatlı ise"], a:"İlaçları yalnızca büyükler verir."},
       {s:"Evde duman gördün. Ne yaparsın?", c:["Büyüğüme haber verir, 112'yi aratırım","Saklanırım","Yatağa girerim","Oyuna devam ederim"], a:"Yangında hemen yardım istenir."},
       {s:"Çıplak elektrik kablosu gördün. Ne yaparsın?", c:["Dokunmaz, büyüğüme söylerim","Çekerim","Sallarım","Ağzıma alırım"], a:"Çıplak kablo tehlikelidir."},
       {s:"Fişi prizden nasıl çıkarırız?", c:["Fişi tutarak","Kabloyu çekerek","Islak elle","Tekmeleyerek"], a:"Fişi tutarak çıkarmak güvenlidir."},
       {s:"Okulda arkadaşını itmek doğru mudur?", c:["Hayır, zarar verebilir","Evet","Bazen","Oyun olduğu için evet"], a:"İtmek yaralanmaya neden olur."},
       {s:"Hangisi güvenli davranıştır?", c:["Makası ucundan tutmadan taşımak","Makasla koşmak","Makası arkadaşına uzatmak","Makası ağzıma almak"], a:"Keskin aletleri dikkatli taşırız."},
       {s:"Temizlik malzemelerini kimler kullanmalı?", c:["Büyükler","Küçük çocuklar","Hayvanlar","Arkadaşlar"], a:"Kimyasallar çocuklar için zararlıdır."}
     ]}
  ]},
  {ad:"Güvenli Hayat", konular:[
    {id:"hb2-trafik-acil", ad:"Trafik Kuralları ve 112", e:"🚑",
     anlat:[
       {b:"Yayalar ve araçlar", m:"Yayalar kaldırımdan yürür. Kaldırım yoksa yolun sol kenarında gideriz. Yolu yaya geçidinden, ışığa bakarak geçeriz. Karşıdan karşıya geçerken sağa ve sola bakarız.", o:"Yeşil yanana kadar beklerim."},
       {b:"Trafik işaretleri", m:"Trafik ışıkları, yaya geçidi ve dur levhası bize yol gösterir. Trafik polisi de elini kaldırınca dururuz. İşaretlere uymak kazaları önler.", o:"Dur levhası kırmızı ve altıgendir."},
       {b:"Araçta güvenlik", m:"Araçta emniyet kemeri takarız. Küçük çocuklar çocuk koltuğunda oturur. Araç dururken kapıyı kaldırım tarafından açarız.", o:"Cama başımızı çıkarmayız."},
       {b:"Acil durumlar", m:"Yangın, kaza, kötü hasta olma gibi tehlikede 112 aranır. Konuşurken adımızı, nerede olduğumuzu ve ne olduğunu söyleriz. Şaka için aramayız.", o:"110 itfaiye, 155 polis, 156 jandarma numaralarıdır."}
     ],
     ipucu:"Dur, bak, dinle, öyle geç! Acil durum: 1-1-2!",
     kartlar:[["Acil çağrı numarası","112"],["İtfaiye numarası","110"],["Polis numarası","155"],["Yolu nereden geçeriz?","Yaya geçidinden"],["Kırmızı ışıkta ne yaparız?","Bekleriz"],["Araçta ne takarız?","Emniyet kemeri"]],
     sorular:[
       {s:"Yayalar yolu nasıl geçmelidir?", c:["Yaya geçidinden, ışığa uyarak","Aniden koşarak","Arabaların arasından","Kırmızı ışıkta"], a:"Yaya geçidi ve ışıklar yayalar için güvenliktir."},
       {s:"Trafik ışığı yeşil yandı. Yine de ne yapmalısın?", c:["Sağa ve sola bakıp geçmeliyim","Gözümü kapatıp koşmalıyım","Hiç bakmamalıyım","Hemen koşmalıyım"], a:"Yeşilde bile sürücülerin durduğundan emin olmalıyız."},
       {s:"Acil durumlarda hangi numara aranır?", c:["112","123","321","987"], a:"112 acil çağrı merkezidir."},
       {s:"Yangın için hangi numara da kullanılabilir?", c:["110","155","156","177"], a:"110 itfaiye numarasıdır; 112 ile de yardım istenebilir."},
       {s:"112'yi arayınca ilk söylememiz gereken önemli bilgi hangisidir?", c:["Olayın nerede olduğu","En sevdiğimiz yemek","Okul notumuz","Rengimiz"], a:"Yardım ekiplerinin gelebilmesi için adresi söyleriz."},
       {s:"112'yi şaka için aramak neden yanlıştır?", c:["Gerçek acil durumları geciktirir","Telefon bozulur","Arkadaşlar kızar","Para öderiz"], a:"Gereksiz arama yardıma muhtaç kişileri bekletir."},
       {s:"Küçük çocuklar arabada nerede oturmalıdır?", c:["Çocuk koltuğunda, arka tarafta","Ön koltukta ayakta","Bagajda","Direksiyonun yanında"], a:"Çocuk koltuğu ve arka koltuk daha güvenlidir."},
       {s:"Kaldırım yoksa yolun hangi tarafında yürürüz?", c:["Sol tarafında","Ortasında","Sağ tarafında, arkamızı dönerek","Fark etmez"], a:"Kaldırım yoksa araçları görmek için yolun sol kenarından yürürüz."},
       {s:"Hangisi güvenli bir davranıştır?", c:["Arabadan kaldırım tarafından inmek","Kapıyı yol tarafında açmak","Yola aniden çıkmak","Cama çıkmak"], a:"Kaldırım tarafı daha güvenlidir."},
       {s:"Sokakta kaybolduğunu fark ettin. Ne yapmalısın?", c:["Polise ya da bir görevliye yardım istemeliyim","Yalnız yürümeliyim","Yabancıyla gitmeliyim","Hiçbir şey yapmamalıyım"], a:"Güvenilir kişilerden yardım istenir."}
     ]
    },
    {id:"hb2-afet-deprem", ad:"Afetler ve Deprem", e:"🏚️",
     anlat:[
       {b:"Afet nedir?", m:"Deprem, sel, yangın ve fırtına doğal afetlerdir. Afetler insanlara zarar verebilir. Hazırlıklı olursak zararı azaltırız.", o:"Ülkemizde deprem sık görülür."},
       {b:"Deprem anında", m:"Sallanma başlayınca Çök-Kapan-Tutun yaparız. Sağlam bir masanın altına gireriz, başımızı koruruz. Pencere ve camlardan uzak dururuz.", o:"Sallanırken koşarak dışarı çıkmayız."},
       {b:"Depremden sonra", m:"Sallanma bitince öğretmenin ya da büyüklerin yönlendirmesiyle güvenli yere gideriz. Asansör kullanmayız. Toplanma alanında bekleriz.", o:"Toplanma alanı açık ve güvenli bir yerdir."},
       {b:"Hazırlık", m:"Afet çantasında su, el feneri, düdük, ilk yardım malzemesi bulunur. Ailemizle toplanma yerini ve telefon numaralarını konuşuruz. Yangında 112'yi ararız.", o:"Düdük, yardım istemek için kullanılır."}
     ],
     ipucu:"Çök, kapan, tutun! Sonra güvenli yere git.",
     kartlar:[["Deprem anında ne yaparız?","Çök-Kapan-Tutun"],["Depremde nereye gireriz?","Sağlam masanın altına"],["Depremde neyden uzak dururuz?","Cam ve pencereden"],["Afet çantasında ne bulunur?","Su, fener, düdük"],["Sallanma bitince nereye gideriz?","Toplanma alanına"],["Depremden sonra ne kullanmayız?","Asansör"]],
     sorular:[
       {s:"Deprem sırasında ne yapılmalıdır?", c:["Çök-Kapan-Tutun","Balkona koşmak","Pencereye yaklaşmak","Asansöre binmek"], a:"Çök-Kapan-Tutun deprem anında önerilen güvenli davranıştır."},
       {s:"Deprem sırasında sınıfta nereye girmeliyiz?", c:["Sağlam sıranın altına","Pencerenin yanına","Dolabın önüne","Kapının önüne"], a:"Sağlam masa ya da sıra başımızı düşen eşyalardan korur."},
       {s:"Depremden sonra hangisini kullanmayız?", c:["Asansör","Merdiven","Toplanma alanı","Düdük"], a:"Deprem sonrası asansör tehlikelidir."},
       {s:"Afet çantasında hangisi bulunur?", c:["Düdük","Oyuncak araba","Çikolata kutusu","Resim defteri"], a:"Düdük, yardım çağırmak için çok yararlıdır."},
       {s:"Toplanma alanı nasıl bir yerdir?", c:["Açık ve güvenli","Dar ve kapalı","Bina içinde","Pencere altında"], a:"Toplanma alanı yıkılabilecek yapılardan uzak, açık bir alandır."},
       {s:"Hangisi doğal afettir?", c:["Sel","Bayram","Yağmur çiçeği","Piknik"], a:"Sel doğal bir afettir."},
       {s:"Okulda deprem tatbikatı neden yapılır?", c:["Doğru davranışı öğrenmek için","Derse girmemek için","Eğlenmek için","Yarışmak için"], a:"Tatbikat gerçek afette paniği azaltmak için yapılır."},
       {s:"Evde yangın başlarsa ne yaparız?", c:["Dışarı çıkıp 112'yi ya da 110'u ararız","Eşyaları toplarız","Saklanırız","Perde çekeriz"], a:"Önce güvenle dışarı çıkıp yardım isteriz."},
       {s:"Arkadaşların sallanırken koşuşuyor. Sen ne yaparsın?", c:["Çök-Kapan-Tutun yaparım","Onlarla koşarım","Bağırırım","Kapıya iterek çıkarım"], a:"Panik yerine doğru davranışı uygulamak güvenlidir."},
       {s:"Ailenle afete hazırlık için hangisi yararlıdır?", c:["Toplanma yerini ve iletişim yolunu önceden konuşmak","Hiç konuşmamak","Çantasız gezmek","Telefonu kapatmak"], a:"Önceden plan yapmak afette kayıpları ve korkuyu azaltır."}
     ]
    }
  ]},
  {ad:"Yaşadığım Yer ve Ülkem", konular:[
    {id:"hb2-bayram-ataturk", ad:"Atatürk, Bayraklar ve Bayramlar", e:"🇹🇷",
     anlat:[
       {b:"Atatürk", m:"Mustafa Kemal Atatürk 1881'de Selanik'te doğdu. Kurtuluş Savaşı'nı yönetti ve Türkiye Cumhuriyeti'ni 29 Ekim 1923'te kurdu. Çocukları ve eğitimi çok önemserdi.", o:"Atatürk, 23 Nisan'ı çocuklara armağan etmiştir."},
       {b:"Millî bayramlar", m:"23 Nisan Ulusal Egemenlik ve Çocuk Bayramı, 19 Mayıs Atatürk'ü Anma Gençlik ve Spor Bayramı, 30 Ağustos Zafer Bayramı ve 29 Ekim Cumhuriyet Bayramı'dır.", o:"29 Ekim'de Cumhuriyet'in ilanını kutlarız."},
       {b:"Millî semboller", m:"Bayrağımız, İstiklal Marşı ve Atatürk'ün resmi millî değerlerimizdir. İstiklal Marşı'nı Mehmet Akif Ersoy yazmıştır. 10 Kasım'da Atatürk'ü saygıyla anarız.", o:"10 Kasım'da saat 09.05'te saygı duruşu yaparız."},
       {b:"Dinî bayramlar", m:"Ramazan Bayramı ve Kurban Bayramı dinî bayramlarımızdır. Bayramlarda akrabaları ziyaret eder, büyüklerin elini öperiz. Birbirimizle paylaşırız.", o:"Bayramlarda harçlık ve şeker alırız."}
     ],
     ipucu:"23 Nisan çocuk, 19 Mayıs genç, 30 Ağustos zafer, 29 Ekim Cumhuriyet!",
     kartlar:[["Çocuk Bayramı","23 Nisan"],["Gençlik ve Spor Bayramı","19 Mayıs"],["Zafer Bayramı","30 Ağustos"],["Cumhuriyet Bayramı","29 Ekim"],["Atatürk'ü anma günü","10 Kasım"],["İstiklal Marşı'nın şairi","Mehmet Akif Ersoy"]],
     sorular:[
       {s:"Cumhuriyet hangi tarihte ilan edilmiştir?", c:["29 Ekim 1923","23 Nisan 1920","30 Ağustos 1922","10 Kasım 1938"], a:"Türkiye Cumhuriyeti 29 Ekim 1923'te ilan edildi."},
       {s:"Atatürk'ün doğduğu şehir hangisidir?", c:["Selanik","Ankara","İzmir","Bursa"], a:"Atatürk 1881'de Selanik'te doğmuştur."},
       {s:"23 Nisan hangi bayramdır?", c:["Ulusal Egemenlik ve Çocuk Bayramı","Zafer Bayramı","Cumhuriyet Bayramı","Gençlik Bayramı"], a:"23 Nisan Ulusal Egemenlik ve Çocuk Bayramı'dır."},
       {s:"19 Mayıs'ta hangi bayramı kutlarız?", c:["Atatürk'ü Anma, Gençlik ve Spor Bayramı","Zafer Bayramı","Çocuk Bayramı","Yeni Yıl"], a:"19 Mayıs, Atatürk'ü Anma, Gençlik ve Spor Bayramı'dır."},
       {s:"Zafer Bayramı hangi tarihtedir?", c:["30 Ağustos","23 Nisan","19 Mayıs","10 Kasım"], a:"Büyük Taarruz'un zaferi 30 Ağustos'ta kutlanır."},
       {s:"Atatürk'ü anma günü hangisidir?", c:["10 Kasım","29 Ekim","19 Mayıs","1 Mayıs"], a:"Atatürk 10 Kasım 1938'de vefat etmiştir."},
       {s:"İstiklal Marşı'nı kim yazmıştır?", c:["Mehmet Akif Ersoy","Nazım Hikmet","Yunus Emre","Orhan Veli"], a:"İstiklal Marşı'nın söz yazarı Mehmet Akif Ersoy'dur."},
       {s:"Hangisi dinî bayramdır?", c:["Kurban Bayramı","Cumhuriyet Bayramı","Zafer Bayramı","Çocuk Bayramı"], a:"Ramazan ve Kurban Bayramı dinî bayramlardır."},
       {s:"Başkentimiz neresidir?", c:["Ankara","İstanbul","Bursa","Konya"], a:"Türkiye'nin başkenti Ankara'dır."},
       {s:"Atatürk, hangi günü çocuklara armağan etmiştir?", c:["23 Nisan","29 Ekim","1 Ocak","10 Kasım"], a:"Atatürk 23 Nisan'ı dünya çocuklarına armağan etmiştir."}
     ]
    },
    {id:"hb2-adres-yasadigim-yer", ad:"Adresim ve Yaşadığım Yer", e:"📍",
     anlat:[
       {b:"Adresim", m:"Adres, evimizin yerini gösterir. Adreste mahalle, sokak, bina ve kapı numarası, ilçe ve il bulunur. Adresimi ezbere bilirim.", o:"Adresimi öğretmenime söylerim."},
       {b:"Mahalle ve çevre", m:"Evimizin çevresinde okul, park, market, sağlık ocağı ve cami gibi yerler olabilir. Bu yerler ortak kullandığımız yerlerdir.", o:"Parkı temiz tutarım."},
       {b:"Köy ve şehir", m:"Köyde tarım ve hayvancılık yaygındır. Şehirde apartmanlar, işyerleri ve okullar daha çoktur. Hepsinde insanlar çalışıp yaşar.", o:"Köyde tarla, şehirde fabrika olur."},
       {b:"Yön bulma", m:"Güneş doğudan doğar, batıdan batar. Yönler kuzey, güney, doğu ve batıdır. Haritalar bize yer bulmada yardım eder.", o:"Güneş sabah doğudan doğar."}
     ],
     ipucu:"Güneş doğudan doğar, batıdan batar! Adresimi bilirim.",
     kartlar:[["Evimizin yerini gösteren","Adres"],["Güneş nereden doğar?","Doğudan"],["Güneş nerede batar?","Batıda"],["Yerleri gösteren çizim","Harita"],["Ortak kullanılan yer","Park"],["Köylerde yaygın iş","Tarım"]],
     sorular:[
       {s:"Evimizin yerini ne gösterir?", c:["Adres","Kimlik","Defter","Çanta"], a:"Adres evimizin yerini belirtir."},
       {s:"Güneş sabah nereden doğar?", c:["Doğu","Batı","Kuzey","Güney"], a:"Güneş doğudan doğar."},
       {s:"Güneş hangi yönde batar?", c:["Batı","Doğu","Kuzey","Güney"], a:"Güneş batıdan batar."},
       {s:"Yer bulmamıza yardım eden çizime ne denir?", c:["Harita","Takvim","Resim","Şiir"], a:"Harita yerleri gösterir."},
       {s:"Hangisi ortak kullandığımız bir yerdir?", c:["Park","Yatak odam","Çantam","Oyuncağım"], a:"Park herkesin kullandığı yerdir."},
       {s:"Köylerde yaygın olan iş hangisidir?", c:["Tarım ve hayvancılık","Gökdelen inşası","Metro sürücülüğü","Otopark işletmeciliği"], a:"Köyde tarım ve hayvancılık yaygındır."},
       {s:"Adresimde hangisi bulunmaz?", c:["Doğum günüm","Mahalle adı","Sokak adı","Kapı numarası"], a:"Adres yer bilgisini içerir."},
       {s:"Parkta çöp atmamak neden önemlidir?", c:["Ortak alan temiz kalır","Çöp güzel görünür","Hayvanlar küser","Park küçülür"], a:"Ortak alanları temiz tutmak herkesin görevidir."},
       {s:"Okulumuz hangi tür yerdir?", c:["Ortak kullanılan bir yer","Sadece öğretmenin yeri","Evimiz","Sadece bir işyeri"], a:"Okul öğrencilerin ve çalışanların ortak yeridir."},
       {s:"Kaybolursan adresini bilmen neden önemlidir?", c:["Eve ulaşmama yardım eder","Daha hızlı koşmamı sağlar","Havayı değiştirir","Yemek bulmamı sağlar"], a:"Adres bilgisi eve dönmemizi kolaylaştırır."}
     ]},
    {id:"hb2-kultur-oyun", ad:"Kültürümüz ve Oyunlarımız", e:"🎎",
     anlat:[
       {b:"Kültür", m:"Yemeklerimiz, oyunlarımız, giysilerimiz, türkülerimiz ve bayramlarımız kültürümüzün parçalarıdır.", o:"Yemekte baklava, çorba."},
       {b:"Geleneksel oyunlar", m:"Birdirbir, uzun eşek, çelik çomak, saklambaç ve ip atlama geleneksel oyunlarımızdır. Bu oyunlar arkadaşlığı güçlendirir.", o:"Çelik çomak eski bir oyundur."},
       {b:"Halk oyunları", m:"Halk oyunları bölgeden bölgeye değişir. Zeybek, horon ve halay bunlardan bazılarıdır. Müzikle birlikte oynanır.", o:"Horon Karadeniz'in oyunudur."},
       {b:"Kültürü yaşatmak", m:"Büyüklerimizden masal, ninni ve türkü dinleriz. Geleneklerimizi öğrenir, bize öğretilenleri başkalarına aktarırız.", o:"Büyükannemden masal dinlerim."}
     ],
     ipucu:"Oyun, türkü, yemek, bayram: Hepsi kültürümüzün parçası!",
     kartlar:[["Karadeniz'in oyunu","Horon"],["Ege'nin oyunu","Zeybek"],["Eski bir sokak oyunu","Çelik çomak"],["Kültür neyi içerir?","Yemek, oyun, giysi"],["Büyüklerden dinlediğimiz","Masal"],["Bebek uyutan söz","Ninni"]],
     sorular:[
       {s:"Hangisi geleneksel bir oyunumuzdur?", c:["Saklambaç","Bilgisayar oyunu","Tablet oyunu","Konsol oyunu"], a:"Saklambaç geleneksel bir sokak oyunudur."},
       {s:"Horon hangi bölgemizle anılır?", c:["Karadeniz","Ege","Akdeniz","İç Anadolu"], a:"Horon Karadeniz'in halk oyunudur."},
       {s:"Hangisi halk oyunudur?", c:["Zeybek","Futbol","Basketbol","Yüzme"], a:"Zeybek Ege'nin halk oyunudur."},
       {s:"Bebekleri uyutmak için söylenen şarkıya ne denir?", c:["Ninni","Marş","Tekerleme","Bilmece"], a:"Bebekler için söylenen şarkılara ninni denir."},
       {s:"Hangisi kültürümüzün bir parçasıdır?", c:["Yemeklerimiz","Hava durumu","Yıldızlar","Dağ yükseklikleri"], a:"Yemek, giysi, oyun ve bayram kültürdür."},
       {s:"Geleneksel oyunlar neden değerlidir?", c:["Arkadaşlığı güçlendirir","Ekranda oynanır","Para harcatır","Tek kişi oynar"], a:"Beraber oynanır, paylaşmayı öğretir."},
       {s:"Kültürümüzü yaşatmak için ne yaparız?", c:["Gelenekleri öğrenip yaşatırız","Onları unuturuz","Yasaklarız","Saklarız"], a:"Büyüklerimizden öğrenip aktarırız."},
       {s:"Masalları genellikle kimden dinleriz?", c:["Büyüklerimizden","Yalnızca bilgisayardan","Yalnızca ekranlardan","Hayvanlardan"], a:"Masallar kuşaktan kuşağa aktarılır."},
       {s:"Hangi iki öge kültürü oluşturur?", c:["Türkü ve bayram","Yağmur ve kar","Güneş ve ay","Taş ve toprak"], a:"Türküler ve bayramlar kültürümüzdür."},
       {s:"İp atlama ne tür oyundur?", c:["Hareketli bir oyun","Masa oyunu","Sessiz oyun","Dijital oyun"], a:"İp atlamak hareketli bir oyundur."}
     ]},
    {id:"hb2-doga-mevsim-cevre", ad:"Mevsimler, Doğa ve Çevre", e:"🌳",
     anlat:[
       {b:"Mevsimler ve değişim", m:"Dünya Güneş'in çevresinde dönerken mevsimler oluşur. İlkbaharda doğa canlanır, yazın hava sıcak olur, sonbaharda yapraklar dökülür, kışın hava soğur ve kar yağabilir.", o:"Kış uykusuna yatan hayvanlar vardır."},
       {b:"Bitki ve hayvanlar", m:"Bitkiler su, ışık ve topraktan beslenir. Hayvanların yaşadığı yerler farklıdır: balık suda, kuş havada, kedi karada. Bazı hayvanlar kışın göç eder.", o:"Leylekler sonbaharda sıcak ülkelere gider."},
       {b:"Çevreyi korumak", m:"Ağaç dikmek, çöp atmamak ve suyu tasarruflu kullanmak çevreyi korur. Kirlilik hayvanlara ve bize zarar verir. Doğal alanlar hepimizindir.", o:"Piknikte çöplerimi geri alırım."},
       {b:"Geri dönüşüm", m:"Kâğıt, cam, plastik ve metal atıklar ayrı toplanır, yeniden işlenir. Böylece doğal kaynaklar korunur ve çöp azalır. Sıfır atık, çöpü en aza indirme hedefidir.", o:"Eski kavanozu saklama kabı olarak kullanırız."}
     ],
     ipucu:"Azalt, yeniden kullan, geri dönüştür: Doğayı sevenin üç adımı!",
     kartlar:[["Yaprakların döküldüğü mevsim","Sonbahar"],["Bitkiler neden beslenir?","Su, ışık ve toprak"],["Balık nerede yaşar?","Suda"],["Geri dönüşebilen atıklar","Kâğıt, cam, plastik, metal"],["Çevreyi koruyan davranış","Ağaç dikmek"],["Kış uykusuna yatan hayvan","Ayı"]],
     sorular:[
       {s:"Hangi mevsimde ağaçların yaprakları dökülür?", c:["Sonbahar","İlkbahar","Yaz","Kış ortası"], a:"Yapraklar sonbaharda dökülür."},
       {s:"Bitkilerin büyümesi için hangisi gereklidir?", c:["Su ve ışık","Plastik","Cam","Gürültü"], a:"Bitkiler su, ışık ve topraktan yararlanarak büyür."},
       {s:"Hangi canlı suda yaşar?", c:["Balık","Kedi","Karga","At"], a:"Balıklar suda yaşar."},
       {s:"Hangisi bir hayvanın göç etmesine örnektir?", c:["Leyleğin sıcak yerlere gitmesi","Kedinin süt içmesi","Köpeğin havlaması","Balığın yüzmesi"], a:"Bazı kuşlar soğuktan korunmak için göç eder."},
       {s:"Hangisi geri dönüşüm kutusuna atılır?", c:["Boş cam kavanoz","Kullanılmış mendil","Yemek artığı","Kırık oyuncak kumaşı"], a:"Cam geri dönüştürülebilir."},
       {s:"Çevre kirliliğini azaltmak için hangisini yapmalıyız?", c:["Çöpleri ayırıp atmalıyız","Çöpleri sokağa atmalıyız","Ağaç kesmeliyiz","Suyu israf etmeliyiz"], a:"Çöpü ayırmak ve doğru yere atmak kirliliği azaltır."},
       {s:"Kış uykusuna yatan hayvan hangisidir?", c:["Ayı","Kedi","Köpek","İnek"], a:"Ayı gibi bazı hayvanlar kışın uyku haline geçer."},
       {s:"Hangi davranış doğaya zarar verir?", c:["Ormanda ateş yakıp söndürmeden gitmek","Fidan dikmek","Çöp toplamak","Suyu kapatmak"], a:"Söndürülmemiş ateş orman yangınına yol açabilir."},
       {s:"Sıfır atık ne demektir?", c:["Atığı en aza indirmek","Hiç yiyecek almamak","Çok çöp biriktirmek","Çöp yakmak"], a:"Sıfır atık, israfı önleyip atığı azaltmak ve yeniden kullanmaktır."},
       {s:"Kullanılmış kâğıtları ne yapmak çevre için en iyisidir?", c:["Geri dönüşüme vermek","Yakmak","Dereye atmak","Yere atmak"], a:"Kâğıt geri dönüştürülünce ağaç kesimi azalır."}
     ]
    },
    {id:"hb2-hayvan-bitki-bakim", ad:"Canlılara Bakım ve Yaşam Alanları", e:"🐝",
     anlat:[
       {b:"Canlıların ihtiyaçları", m:"Bitkiler su, ışık, hava ve toprak ister. Hayvanlar yemek, su, hava ve barınak ister. Bu ihtiyaçlar karşılanmazsa canlılar zarar görür.", o:"Çiçeği sularım."},
       {b:"Yaşam alanları", m:"Balık suda, kuş havada ve ağaçta, tilki ormanda yaşar. Her canlının kendi yaşam alanı vardır. Onu bozmayız.", o:"Balık suda yaşar."},
       {b:"Hayvanlara iyi davranmak", m:"Hayvanlara vurmam, taş atmam. Evcil hayvanımın yemeğini ve suyunu veririm. Sahipsiz hayvanlara zarar vermem.", o:"Kediye su veririm."},
       {b:"Bitkilere bakım", m:"Bitkileri düzenli sularım. Çiçekleri koparmam. Ağaç dikmek doğayı güzelleştirir ve oksijen üretilmesini sağlar.", o:"Fidan dikerim."}
     ],
     ipucu:"Bitkiye su, hayvana yem; yaşam alanı onların evi!",
     kartlar:[["Bitkinin ihtiyacı","Su ve ışık"],["Balığın yaşam alanı","Su"],["Kuşların evi","Yuva"],["Ağaçlar neyi üretir?","Oksijen"],["Hayvana ne yapmayız?","Zarar vermeyiz"],["Fidan dikmek neyi korur?","Doğayı"]],
     sorular:[
       {s:"Bitkilerin yaşaması için hangisi gereklidir?", c:["Su ve ışık","Plastik","Şeker","Boya"], a:"Bitkiler su, ışık, hava ve toprak ister."},
       {s:"Balık nerede yaşar?", c:["Suda","Havada","Mağarada","Çölde"], a:"Balık suda yaşayan bir canlıdır."},
       {s:"Kuşların yaşadığı yere ne denir?", c:["Yuva","Mutfak","Banyo","Atölye"], a:"Kuşlar yuvalarda yaşar."},
       {s:"Ağaçlar bize ne verir?", c:["Oksijen","Plastik","Şeker","Kum"], a:"Ağaçlar havadaki gazı temizler, oksijen verir."},
       {s:"Evcil hayvana ne vermeliyiz?", c:["Yemek ve su","Taş","Boya","Plastik"], a:"Canlıların temel ihtiyaçları karşılanmalıdır."},
       {s:"Hayvanlara karşı nasıl davranmalıyız?", c:["Nazik ve şefkatli","Sert","Korkutucu","Umursamaz"], a:"Hayvanlara saygı gösteririz."},
       {s:"Hangisi bir yaşam alanıdır?", c:["Orman","Defter","Sandalye","Çanta"], a:"Orman birçok canlının yaşam alanıdır."},
       {s:"Çiçeği koparmak yerine ne yapmalıyız?", c:["Bakıp sulamalıyız","Ezmeliyiz","Atmalıyız","Boyamalıyız"], a:"Çiçeği korumak doğayı korur."},
       {s:"Hangisi doğaya zarar verir?", c:["Ormanda çöp bırakmak","Fidan dikmek","Çöpü toplamak","Çiçeği sulamak"], a:"Çöp doğayı kirletir."},
       {s:"Bir canlı yaşam alanı bozulursa ne olur?", c:["Zarar görür","Daha mutlu olur","Hiçbir şey olmaz","Daha hızlı büyür"], a:"Yaşam alanı bozulursa canlılar yaşayamaz."}
     ]}
  ]},
  {ad:"Bilim, Teknoloji ve Sanat", konular:[
    {id:"hb2-meslek-teknoloji", ad:"Meslekler ve Teknoloji", e:"🧑‍🔬",
     anlat:[
       {b:"Meslekler", m:"Doktor hastaları iyileştirir, öğretmen öğretir, itfaiyeci yangın söndürür, çiftçi ürün yetiştirir. Her meslek topluma yararlıdır. Meslekler birbirini tamamlar.", o:"Fırıncı ekmek yapar, kasap et satar."},
       {b:"Neden çalışırız?", m:"İnsanlar ihtiyaçlarını karşılamak ve topluma hizmet etmek için çalışır. Büyüyünce yeteneklerime ve ilgilerime göre meslek seçebilirim.", o:"Ben büyüyünce veteriner olmak istiyorum."},
       {b:"Teknoloji", m:"Teknoloji hayatımızı kolaylaştıran araçlardır: telefon, bilgisayar, çamaşır makinesi, tablet. Doğru kullanılırsa öğrenmemize yardım eder.", o:"Bilgisayarla ödev araştırması yaparız."},
       {b:"Bilinçli kullanım", m:"Teknolojiyi ailemizin izniyle ve belirli sürelerde kullanırız. Ekranda uzun kalmak gözlerimize zarar verir. İnternette tanımadığımız kişilerle konuşmayız, kişisel bilgilerimizi paylaşmayız.", o:"Şifremi kimseyle paylaşmam."}
     ],
     ipucu:"Ekran kısa, göz dinlensin; şifre gizli, yabancıya konuşma yok!",
     kartlar:[["Yangın söndüren","İtfaiyeci"],["Hastaları iyileştiren","Doktor"],["Ürün yetiştiren","Çiftçi"],["Hayvanların doktoru","Veteriner"],["Bilgisayar, telefon","Teknoloji araçları"],["Şifreyi kimlerle paylaşırız?","Hiç kimseyle"]],
     sorular:[
       {s:"Yangın söndüren meslek hangisidir?", c:["İtfaiyeci","Fırıncı","Öğretmen","Terzi"], a:"İtfaiyeciler yangınları söndürür ve kurtarma yapar."},
       {s:"Ekmek yapan kişinin mesleği nedir?", c:["Fırıncı","Marangoz","Pilot","Berber"], a:"Ekmeği fırıncı yapar."},
       {s:"Hayvanları tedavi eden meslek hangisidir?", c:["Veteriner","Eczacı","Mimar","Garson"], a:"Veterinerler hayvanların sağlığıyla ilgilenir."},
       {s:"İnsanlar neden çalışır?", c:["İhtiyaçlarını karşılamak ve topluma hizmet etmek için","Sadece vakit geçirmek için","Hiç dinlenmemek için","Çocukları üzmek için"], a:"Çalışarak hem kazanır hem topluma yardımcı olur."},
       {s:"Hangisi teknolojik bir araçtır?", c:["Tablet","Tahta kaşık","Taş","Kil çanak"], a:"Tablet teknolojik bir cihazdır."},
       {s:"Teknolojiyi nasıl kullanmalıyız?", c:["Ailemizin bilgisi ve izniyle","Gizli gizli","Gece geç saate kadar","Sürekli açık bırakarak"], a:"Bilinçli kullanım için aileyle birlikte kurallar belirleriz."},
       {s:"Ekranda uzun süre kalmanın zararı nedir?", c:["Gözlerimiz yorulur","Boyumuz uzar","Saçlarımız uzar","Dişlerimiz güçlenir"], a:"Uzun süre ekrana bakmak göz ve vücut sağlığına zarar verir."},
       {s:"İnternette tanımadığın biri seninle konuşmak istedi. Ne yaparsın?", c:["Yanıt vermez, aileme haber veririm","Adımı ve adresimi veririm","Okulumu söylerim","Fotoğrafımı gönderirim"], a:"Yabancılarla iletişim kurmayıp ailemize haber vermeliyiz."},
       {s:"Bir mesleği seçerken neye dikkat edebiliriz?", c:["İlgi ve yeteneklerimize","Sadece arkadaşımızın seçimine","Rastgele bir şeye","Hiç düşünmeden"], a:"Meslek seçiminde ilgi ve yetenek önemlidir."},
       {s:"Çamaşır makinesi insanlara ne sağlar?", c:["Zaman kazandırır, işi kolaylaştırır","Daha çok iş çıkarır","Hiçbir yarar sağlamaz","Sadece gürültü yapar"], a:"Teknoloji günlük işleri kolaylaştırır."}
     ]
    },
    {id:"hb2-bilim-sanat-spor", ad:"Merak, Bilim, Sanat ve Spor", e:"🔬",
     anlat:[
       {b:"Merak ve gözlem", m:"Bilim merakla başlar. Gözlem yapar, soru sorar, denerim. Bir şeyi gözlemlerken gözlerimi, kulaklarımı ve ellerimi kullanırım.", o:"Buz erirken gözlerim."},
       {b:"Bilim insanları", m:"Bilim insanları araştırır ve deney yapar. Yeni şeyler öğrenir ve bulur. Bilimsel buluşlar hayatımızı kolaylaştırır.", o:"Aşıyı bilim insanları buldu."},
       {b:"Sanat", m:"Resim, müzik, tiyatro ve heykel birer sanattır. Sanat duygularımızı anlatmamızı sağlar. Müzeler ve sergiler sanat eserlerini gösterir.", o:"Müzede resim izlerim."},
       {b:"Spor", m:"Futbol, yüzme, voleybol ve atletizm spordur. Spor sağlıklıdır. Spor yaparken kurallara uyarım ve rakibime saygı gösteririm.", o:"Yüzmek güzel bir spordur."}
     ],
     ipucu:"Merak et, gözlemle, dene! Sanat duyguyu, spor sağlığı güçlendirir.",
     kartlar:[["Deney ve araştırma yapan","Bilim insanı"],["Resim, müzik, heykel","Sanat"],["Futbol, yüzme","Spor"],["Eserlerin sergilendiği yer","Müze"],["Bilimin başlangıcı","Merak"],["Spor yapınca rakibe nasıl davranırız?","Saygıyla"]],
     sorular:[
       {s:"Bilim neyle başlar?", c:["Merakla","Korkuyla","Tembellikle","Kızgınlıkla"], a:"Merak soru sormaya ve araştırmaya götürür."},
       {s:"Deney ve araştırma yapan kişiye ne denir?", c:["Bilim insanı","Şoför","Garson","Çiftçi"], a:"Bilim insanları araştırma yapar."},
       {s:"Hangisi bir sanat dalıdır?", c:["Resim","Futbol","Yüzme","Koşu"], a:"Resim görsel bir sanattır."},
       {s:"Sanat eserlerini görmek için nereye gideriz?", c:["Müzeye","Bakkala","Fırına","Hastaneye"], a:"Müzelerde sanat eserleri sergilenir."},
       {s:"Hangisi bir spor dalıdır?", c:["Voleybol","Resim","Heykel","Şiir"], a:"Voleybol bir takım sporudur."},
       {s:"Gözlem yapmak için hangisini kullanırız?", c:["Duyu organlarımızı","Yalnızca kalemimizi","Yalnızca çantamızı","Ayakkabılarımızı"], a:"Gözlemde duyu organları kullanılır."},
       {s:"Spor yaparken rakibimize nasıl davranmalıyız?", c:["Saygıyla","Alay ederek","İterek","Küsüp"], a:"Spor fair-play ile güzeldir."},
       {s:"Hangisi bilimin bize katkısıdır?", c:["Hastalıklara çare bulmak","Hava kirletmek","Çöp üretmek","Vakit kaybettirmek"], a:"Bilim sağlık ve yaşamı kolaylaştırır."},
       {s:"Sanat bize ne sağlar?", c:["Duygularımızı anlatma imkânı","Yalnızca para","Hastalık","Gürültü"], a:"Sanat duyguları ifade etmeyi sağlar."},
       {s:"Bir deney yaparken ne yapmalıyız?", c:["Dikkatli ve güvenli olmalıyız","Acele etmeliyiz","Yalnız yapmalıyız","Kuralsız olmalıyız"], a:"Güvenlik kurallarına uyarız."}
     ]}
  ]}
]});
